/**
 * Typed loaders for the oracle's data assets (A1: rules as queryable data,
 * never static prompt text). All files live in ../data and are generated by
 * scripts/build-data.ts or maintained by hand (emag.json, ds-page-rules.json).
 */
import { readFileSync } from "node:fs";
import type { DsStylesheetIndex } from "../evidence/cssProvenance.js";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { guardKnowledge } from "./lock.js";
import { structureTagGrounding } from "../checkers/grounding.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
// Works from both src/ (tsx) and dist/ (compiled) since data/ sits at package root.
const DATA_DIR = join(__dirname, "../../data");

export interface TokenRegistry {
  meta: { source: string; version: string; generatedAt: string; totalTokens: number };
  semantic: Record<string, { token: string; value: string }>;
  hexLookup: Record<string, string[]>;
  categorized: Record<string, Record<string, string>>;
  all: Record<string, string>;
}

export interface EmagRule {
  id: string;
  title: string;
  description: string;
  wcag: string | null;
}

export interface EmagData {
  meta: { source: string; authority: string; url: string; note: string };
  sections: Record<string, { title: string; rules: EmagRule[] }>;
}

export interface PageRulesData {
  meta: { source: string; url: string; scrapedAt: string; note?: string } & Record<string, unknown>;
  categories: Record<string, { label: string; url: string; rules?: unknown[]; sections?: Record<string, unknown> } & Record<string, unknown>>;
}

export interface ComponentSpec {
  name: string;
  rootClass: string;
  /** Tags que carregam a classe raiz nos exemplos oficiais de QUALQUER componente (D-51). */
  tags: string[];
  /** De quais componentes vêm os exemplos de cada tag. */
  tagSources?: Record<string, string[]>;
  variantClasses: string[];
  ariaAttributes: string[];
  tokensUsed: string[];
  examples: { name: string; html: string }[];
}

export interface ComponentConstraint {
  /** Stable checker/specification id shared by normative and deterministic profiles (3.6.0: `rule.checker`, not a citation). */
  id: string;
  /** 3.6.0: the normative unit a finding of this constraint cites in `rule.id` (e-MAG 1.2 for semantic roots, anatomy otherwise). */
  citeAs: string;
  kind: "root-tag";
  description: string;
  rootClass: string;
  allowedTags: string[];
}

/**
 * Machine-readable claims exposed with a component specification.
 *
 * The deterministic checker already emitted these ids. Returning them from the normative
 * surface prevents agents from borrowing an unrelated broad KB rule merely because a structural
 * constraint did not have a citable identity (D-29).
 */
/**
 * Tags dos exemplos do PRÓPRIO componente × tags que só aparecem nos exemplos de outros (D-51).
 * `br-button` é `<button>` na pasta do botão e `<a>` no breadcrumb, no footer e no menu — lá ele é
 * um link com aparência de botão. Sem `tagSources` (dados antigos) tudo conta como próprio.
 */
export function ownAndBorrowedTags(spec: ComponentSpec): { own: string[]; borrowed: string[] } {
  const own = spec.tags.filter((tag) => !spec.tagSources || spec.tagSources[tag]?.includes(spec.name));
  return { own, borrowed: spec.tags.filter((tag) => !own.includes(tag)) };
}

/** Tags do exemplo oficial que a verificação da tag raiz espera: as próprias do componente (ou todas, sem origem). */
export function expectedRootTags(spec: ComponentSpec): string[] {
  const { own } = ownAndBorrowedTags(spec);
  return own.length > 0 ? own : spec.tags;
}

export function constraintsForComponent(spec: ComponentSpec): ComponentConstraint[] {
  const { own, borrowed } = ownAndBorrowedTags(spec);
  const ressalva = borrowed.includes("a") ? " <a> vale quando o link navega (href real), como nos exemplos oficiais de outros componentes." : "";
  return spec.tags.length === 0 ? [] : [{
    id: `ds-structure-${spec.name}-tag`,
    citeAs: structureTagGrounding(expectedRootTags(spec))[0],
    kind: "root-tag",
    description: `${spec.rootClass} deve ser aplicado a <${(own.length ? own : spec.tags).join("> ou <")}>.${ressalva}`,
    rootClass: spec.rootClass,
    allowedTags: [...spec.tags],
  }];
}

export interface ComponentSpecsData {
  meta: { source: string; version: string; generatedAt: string; totalComponents: number };
  components: Record<string, ComponentSpec>;
}

function load<T>(filename: string): T {
  return JSON.parse(readFileSync(join(DATA_DIR, filename), "utf8")) as T;
}

let tokens: TokenRegistry | undefined;
let emag: EmagData | undefined;
let pageRules: PageRulesData | undefined;
let componentSpecs: ComponentSpecsData | undefined;
let dsStylesheet: DsStylesheetIndex | undefined;

export function getTokenRegistry(): TokenRegistry {
  guardKnowledge("getTokenRegistry");
  return (tokens ??= load<TokenRegistry>("tokens.json"));
}

export function getEmag(): EmagData {
  guardKnowledge("getEmag");
  return (emag ??= load<EmagData>("emag.json"));
}

export function getPageRules(): PageRulesData {
  guardKnowledge("getPageRules");
  return (pageRules ??= load<PageRulesData>("ds-page-rules.json"));
}

/** Índice das declarações que a folha oficial do DS publica — ver `evidence/cssProvenance.ts`. */
export function getDsStylesheet(): DsStylesheetIndex {
  guardKnowledge("getDsStylesheet");
  return (dsStylesheet ??= load<DsStylesheetIndex>("ds-stylesheet.json"));
}

export function getComponentSpecs(): ComponentSpecsData {
  guardKnowledge("getComponentSpecs");
  return (componentSpecs ??= load<ComponentSpecsData>("component-specs.json"));
}

let componentParts: Record<string, string[]> | undefined;

/**
 * 3.7.8 (leitura dev-374-a2 §5 item 4): os componentes do DS que os exemplos OFICIAIS de cada componente trazem dentro
 * dele (classes raiz `br-*` no HTML dos exemplos, menos a própria) — o radio e o checkbox na lista do select, o botão
 * do input. Um componente achado só como parte do hospedeiro (dentro dele, como no exemplo) é anatomia do hospedeiro.
 */
export function componentPartsOf(): Record<string, string[]> {
  if (componentParts) return componentParts;
  const out: Record<string, string[]> = {};
  for (const [name, spec] of Object.entries(getComponentSpecs().components)) {
    const parts = new Set<string>();
    for (const example of spec.examples ?? []) {
      for (const m of example.html.matchAll(/class="([^"]*)"/g)) {
        for (const c of m[1].split(/\s+/)) if (/^br-[a-z]+$/.test(c) && c !== `br-${name}`) parts.add(c.slice(3));
      }
    }
    if (parts.size) out[name] = [...parts].sort();
  }
  return (componentParts = out);
}

/** Find an e-MAG rule by id (e.g. "3.5") across all sections. */
export function findEmagRule(id: string): (EmagRule & { section: string }) | undefined {
  guardKnowledge("findEmagRule");
  for (const [section, data] of Object.entries(getEmag().sections)) {
    const rule = data.rules.find((r) => r.id === id);
    if (rule) return { ...rule, section };
  }
  return undefined;
}
